for(const code of LANGS){if(!IA[code])IA[code]=[...labels[code],...IA_ENDINGS[code]];IA[code].push(CIVIL_LABELS[code]);}
function it(n){return IA[lang][n]}
const GROUPS={topics:['mapa','belem','testes','thinktanks'],actors:['posicoes','quem'],action:['agenda'],brazil:['brasil'],guide:['panorama','terreno'],calendar:['calendario'],glossary:['glossario'],archive:['radar'],sources:['fontes','privacidade']};
const legacy={hoje:'today',atualizacoes:'pulse',pulso:'pulse/social',newsletter:'explore/sources'};Object.entries(GROUPS).forEach(([g,sections])=>sections.forEach(s=>legacy[s]='explore/'+g+'/'+s));
const LEGACY_ANCHORS={"glanceFeed": "panorama", "posSummary": "posicoes", "posCount": "posicoes", "posEmpty": "posicoes", "timeline": "calendario", "nlCtl": "privacidade", "nlCtlContact": "privacidade", "nlProc": "privacidade", "nlVer": "privacidade"};
let pauseRoute=false;
let feed=null,explores={},positions=null,pulseLimit=25,activeExplore='',loadSeq=0;
function slug(x){return String(x||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function pulseHTML(){return `<div class="filters"><label>${esc(it(12))}<input id="pulse-query" type="search"></label><label>${esc(it(9))}<select id="pulse-kind"><option value="">${esc(it(9))}</option><option value="publication">${esc(it(10))}</option><option value="post">${esc(it(11))}</option></select></label>${['institution','tracks','platform','account'].map((k,i)=>`<label>${esc(it(13+i))}<select id="pulse-${k}"><option value="">${esc(it(9))}</option></select></label>`).join('')}<label>${esc(it(17))}<input id="pulse-from" type="date"></label><label>${esc(it(18))}<input id="pulse-to" type="date"></label><button id="pulse-reset">${esc(t(11))}</button></div><p id="pulse-count" role="status"></p><div id="feed-list"></div><button id="pulse-more">${esc(t(12))}</button>`}
function pulseRows(){if(!feed)return;const v=k=>$('pulse-'+k).value;let rows=feed.items.filter(x=>(!v('kind')||(x.kind||'publication')===v('kind'))&&(!v('query')||slug(JSON.stringify(x)).includes(slug(v('query'))))&&['institution','platform','account'].every(k=>!v(k)||x[k]===v(k))&&(!v('tracks')||(x.tracks||[]).includes(v('tracks')))&&(!v('from')||x.date>=v('from'))&&(!v('to')||x.date<=v('to')));text('pulse-count',`${rows.length} / ${feed.items.length} ${it(31)} · ${date(feed.generated_at)} · ${t(23)}`);$('feed-list').innerHTML=rows.slice(0,pulseLimit).map(x=>`<article class="post" id="record-${esc(x.id)}"><span class="source-type">${esc(x.kind==='post'?it(11):it(10))} · ${esc(x.platform||x.type||'')}</span><h2 dir="auto"><a href="${safeURL(x.url)}">${esc(sourceTitle(x)||x.text||'')}</a></h2><p dir="auto">${esc(description(x))}</p><p class="meta">${esc(x.institution||x.publisher||x.account)} · <bdi>${esc(x.date)} ${esc(x.time||'')}</bdi> · ${esc((x.tracks||[]).join(' / '))}</p><details><summary>${esc(it(8))}</summary><p><bdi>${esc(date(x.first_seen))}</bdi> · <bdi>${esc(x.source_id||'')}</bdi> · <bdi>${esc(x.account||'')}</bdi></p>${(x.variants||[]).map(v=>`<p>${esc(v.id)} · ${esc(v.institution||v.publisher||v.account||'')} · <bdi>${esc(v.date||'')}</bdi> · <bdi>${esc(date(v.first_seen))}</bdi></p>`).join('')}<a href="${safeURL(x.url)}">${esc(t(37))}</a></details></article>`).join('');$('pulse-more').hidden=rows.length<=pulseLimit}
async function loadPulse(){if(!$('pulse-query')){$('posts').innerHTML=pulseHTML();$('posts').querySelectorAll('input,select').forEach(e=>e.addEventListener('input',()=>{pulseLimit=25;pulseRows()}));$('pulse-more').onclick=()=>{pulseLimit+=25;pulseRows()};$('pulse-reset').onclick=()=>{$('posts').querySelectorAll('input,select').forEach(e=>e.value='');pulseLimit=25;pulseRows()};}if(!feed){const r=await fetch(dataURL('feed'));if(!r.ok)throw Error('feed');feed=await r.json();feed.rawCount=feed.items.length;feed.items=canonicalPulseItems(feed.items)}for(const k of ['institution','tracks','platform','account']){let el=$('pulse-'+k),old=el.value;el.innerHTML=`<option value="">${esc(it(9))}</option>`+[...new Set(feed.items.flatMap(x=>x[k]||[]))].sort().map(x=>`<option>${esc(x)}</option>`).join('');el.value=old}if(location.hash==='#pulse/social')$('pulse-kind').value='post';pulseRows()}
function positionRows(){let q=slug($('position-query').value),a=$('position-actor').value,b=$('position-topic').value,c=$('position-standing').value;const rows=positions.filter(x=>(!q||slug(x.join(' ')).includes(q))&&(!a||x[0]===a)&&(!b||x[1]===b)&&(c===''||String(x[3])===c));text('position-count',`${rows.length} / ${positions.length} · Carbon Brief · ${new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeZone:'UTC'}).format(new Date('2026-11-05T12:00:00Z'))}`);$('position-rows').innerHTML=rows.map(x=>`<tr><th scope="row">${esc(x[0])}</th><td>${esc(x[1])}</td><td>${esc(x[2])}</td><td>${esc(it(22+x[3]))}</td></tr>`).join('')}
async function positionUI(){if(!positions){const r=await fetch('positions.json');positions=await r.json()}const el=$('position-tool');if(!el)return;el.innerHTML=`<div class="filters"><label>${esc(it(12))}<input id="position-query" type="search"></label>${[['actor',20,0],['topic',14,1]].map(([k,n,i])=>`<label>${esc(it(n))}<select id="position-${k}"><option value="">${esc(it(9))}</option>${[...new Set(positions.map(x=>x[i]))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></label>`).join('')}<label>${esc(it(19))}<select id="position-standing"><option value="">${esc(it(9))}</option>${[0,1,2,3].map(i=>`<option value="${i}">${esc(it(22+i))}</option>`).join('')}</select></label><button id="position-reset">${esc(t(11))}</button></div><p id="position-count" role="status"></p><div class="table-scroll" tabindex="0"><table><thead><tr>${[20,14,21,19].map(i=>`<th scope="col">${esc(it(i))}</th>`).join('')}</tr></thead><tbody id="position-rows"></tbody></table></div>`;el.querySelectorAll('input,select').forEach(e=>e.oninput=positionRows);$('position-reset').onclick=()=>{el.querySelectorAll('input,select').forEach(e=>e.value='');positionRows()};positionRows()}
async function exploreView(group,section){const seq=++loadSeq,key=lang;const g=GROUPS[group]?group:'topics';$('method').innerHTML=`<nav class="explore-nav" aria-label="${esc(t(3))}">${Object.keys(GROUPS).map((x,i)=>`<a href="#explore/${x}" ${x===g?'aria-current="page"':''}>${esc(it(i))}</a>`).join('')}</nav><p class="freshness">${esc(it(26))}</p><div id="explore-content" aria-live="polite">…</div>`;if(!explores[key]){const r=await fetch('explore-'+key+'.json');explores[key]=await r.json()}if(seq!==loadSeq)return;const e=explores[key];$('explore-content').innerHTML=GROUPS[g].map(s=>`<article class="reference" id="reference-${s}">${s==='radar'?`<p class="archive-label">${esc(it(27))}</p>`:s==='testes'?`<p class="archive-label">${esc(it(28))}</p>`:''}${s==='thinktanks'?`<h2>${esc(it(29))}</h2>`:''}${s==='posicoes'?'<div id="position-tool"></div>':''}${e.sections[s]}</article>`).join('');if(g==='actors')await positionUI();if(section){const target=$('reference-'+section)||$(section);target?.scrollIntoView?.({block:'start'})}activeExplore=g}
const originalRender=render;render=function(){pauseRoute=true;originalRender();pauseRoute=false;text('pulse-title',t(2));$('pulse').querySelector('.eyebrow').textContent=it(10)+' + '+it(11);text('pulse-intro',it(10)+' + '+it(11)+'. '+t(23));text('explore-title',t(3));$('posts').innerHTML='';let extra=$('daily-sections');if(!extra){extra=document.createElement('div');extra.id='daily-sections';$('today').appendChild(extra)}let seen=new Set((data.briefing.sections.essential||[]).slice(0,4).map(x=>x.lead.url));extra.innerHTML=Object.entries(data.briefing.sections).map(([k,items])=>{const unique=items.filter(x=>{if(seen.has(x.lead.url))return false;seen.add(x.lead.url);return true});return unique.length?`<section><h2>${esc(k==='essential'?it(30):({negotiations:t(1),action:it(2),civil:it(32)})[k]||k)}</h2>${unique.map(x=>`<article class="post">${story(x.lead)}${x.related?.length?`<details><summary>${esc(it(29))}</summary>${x.related.map(y=>`<p><a href="${safeURL(y.url)}">${esc(sourceTitle(y))}</a> · ${esc(y.publisher||'')}</p>`).join('')}</details>`:''}</article>`).join('')}</section>`:''}).join('');route()};
route=function(){if(pauseRoute)return;if(location.hash==='#main'){$('main').focus();return}let raw=location.hash.slice(1)||'today';raw=legacy[raw]||raw;const parts=raw.split('/'),id=['today','texts','pulse','explore'].includes(parts[0])?parts[0]:'explore';document.querySelectorAll('.view').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('[data-tab]').forEach(a=>a.setAttribute('aria-current',a.dataset.tab===id?'page':'false'));if(!data)return;if(id==='pulse')loadPulse().catch(()=>text('posts',t(38)));if(id==='explore'){let group=parts[1],section=parts[2];if(!GROUPS[group]&&raw!=='explore'){const sectionName=LEGACY_ANCHORS[raw];if(sectionName){group=Object.keys(GROUPS).find(g=>GROUPS[g].includes(sectionName));section=raw}}exploreView(group,section).catch(()=>text('method',t(38)))}};
window.addEventListener('hashchange',route);
